        grid_axis(
            b[3],
            range.grid_min_y,
            range.grid_cell_size,
            range.grid_rows,
        )? as usize,
    ))
}
pub fn build_stroke_grid(
    view: SceneView<'_>,
    cache: &mut DashCache,
    control: &mut dyn WorkControl,
) -> Result<()> {
    let mut cells_total = 0usize;
    let mut refs_total = 0usize;
    for i in 0..cache.shapes.len() {
        let base_used = cache_used(cache).ok_or_else(limit)?;
        let s = &view.shapes[i];
        let r = &mut cache.shapes[i];
        let primitive = r.segments.count + r.joins.count;
        if primitive == 0 {
            continue;
        }
        control.checkpoint().map_err(stopped)?;
        let radius = s.stroke.width * 0.5;
        let mut minx = f64::INFINITY;
        let mut miny = minx;
        let mut maxx = f64::NEG_INFINITY;
        let mut maxy = maxx;
        for seg in &cache.segments[r.segments.first..r.segments.first + r.segments.count] {
            let Some(b) = bounds_segment(seg, radius) else {
                continue;
            };
            minx = minx.min(b[0]);
            miny = miny.min(b[1]);
            maxx = maxx.max(b[2]);
            maxy = maxy.max(b[3])
        }
        let jr = if s.stroke.join == vexel_scene::Linejoin::Miter {
            radius * s.stroke.miter_limit
        } else {
            radius
        };
        for j in &cache.joins[r.joins.first..r.joins.first + r.joins.count] {
            minx = minx.min(j.vertex.x - jr);
            miny = miny.min(j.vertex.y - jr);
            maxx = maxx.max(j.vertex.x + jr);
            maxy = maxy.max(j.vertex.y + jr)
        }
        let sx = maxx - minx;
        let sy = maxy - miny;
        if !sx.is_finite() || !sy.is_finite() {
            continue;
        }
        let size = 1.0f64.max((sx.max(sy)) / STROKE_GRID_MAX_AXIS as f64);
        let cols = (sx / size).ceil().max(1.0);
        let rows = (sy / size).ceil().max(1.0);
        if cols > 128.0 || rows > 128.0 {
            continue;
        }
        r.grid_min_x = minx;
        r.grid_min_y = miny;
        r.grid_cell_size = size;
        r.grid_columns = cols as u16;
        r.grid_rows = rows as u16;
        let count = (cols as usize)
            .checked_mul(rows as usize)
            .ok_or_else(limit)?;
        if cells_total
            .checked_add(count)
            .is_none_or(|n| n > STROKE_GRID_MAX_CELLS)
        {
            r.grid_columns = 0;
            r.grid_rows = 0;
            continue;
        }
        let mut cells = Vec::new();
        cells.try_reserve_exact(count).map_err(|_| oom())?;
        cells.resize(count, GridCell { first: 0, count: 0 });
        let mut total = 0usize;
        let mut encoded_bounds = Vec::new();
        for (k, seg) in cache.segments[r.segments.first..r.segments.first + r.segments.count]
            .iter()
            .enumerate()
        {
            if let Some(b) = bounds_segment(seg, radius) {
                encoded_bounds.push(((r.segments.first + k) as u32, b));
            } else {
                encoded_bounds.clear();
                break;
            }
        }
        for (k, j) in cache.joins[r.joins.first..r.joins.first + r.joins.count]
            .iter()
            .enumerate()
        {
            encoded_bounds.push((
                STROKE_GRID_JOIN_BIT | ((r.joins.first + k) as u32),
                [
                    j.vertex.x - jr,
                    j.vertex.y - jr,
                    j.vertex.x + jr,
                    j.vertex.y + jr,
                ],
            ))
        }
        let mut fits = true;
        for (_, b) in &encoded_bounds {
            let Some((x0, y0, x1, y1)) = bbox(r, *b) else {
                fits = false;
                break;
            };
            for y in y0..=y1 {
                for x in x0..=x1 {
                    let c = &mut cells[y * cols as usize + x];
                    c.count = c.count.checked_add(1).ok_or_else(limit)?;
                    total = total.checked_add(1).ok_or_else(limit)?
                }
            }
        }
        if !fits
            || refs_total
                .checked_add(total)
                .is_none_or(|x| x > STROKE_GRID_MAX_REFS)
        {
            r.grid_columns = 0;
            r.grid_rows = 0;
            continue;
        }
        let cell_bytes = count
            .checked_mul(std::mem::size_of::<GridCell>())
            .ok_or_else(limit)?;
        let ref_bytes = total.checked_mul(4).ok_or_else(limit)?;
        if base_used
            .checked_add(cell_bytes + ref_bytes)
            .is_none_or(|x| x > DASH_CACHE_BYTE_LIMIT)
        {
            r.grid_columns = 0;
            r.grid_rows = 0;
            continue;
        }
        let mut offset = 0;
        for c in &mut cells {
            let num = c.count;
            c.first = offset;
            c.count = 0;
            offset = offset.checked_add(num).ok_or_else(limit)?
        }
        let mut refs = Vec::new();
        refs.try_reserve_exact(total).map_err(|_| oom())?;
        refs.resize(total, 0);
        for (encoded, b) in encoded_bounds {
            let Some((x0, y0, x1, y1)) = bbox(r, b) else {
                fits = false;
                break;
            };
            for y in y0..=y1 {
                for x in x0..=x1 {
                    let c = &mut cells[y * cols as usize + x];
                    refs[c.first + c.count] = encoded;
                    c.count += 1
                }
            }
        }
        if !fits {
            r.grid_columns = 0;
            r.grid_rows = 0;
            continue;
        }
        r.grid_cells = cells;
        r.grid_refs = refs;
        cells_total += count;
        refs_total += total;
        cache.grid_cell_count = cells_total;
        cache.grid_ref_count = refs_total;
        cache.grid_bytes = cache
            .grid_bytes
            .checked_add(cell_bytes + ref_bytes)
            .ok_or_else(limit)?
    }
    Ok(())
}
use crate::*;
use vexel_geometry::{Point, affine_map_point};
use vexel_scene::{Paint, PaintKind, SceneView, ShapeId};

fn over(dst: &mut [u8; 4], src: [u8; 4]) {
    let sa = src[3] as u32;
    if sa == 0 {
        return;
    }
    let da = dst[3] as u32;
    let inv = 255 - sa;
    let an = sa * 255 + da * inv;
    for c in 0..3 {
        let n = src[c] as u32 * sa * 255 + dst[c] as u32 * da * inv;
        dst[c] = ((n + an / 2) / an) as u8
    }
    dst[3] = ((an + 127) / 255) as u8
}
fn image_sample(
    view: SceneView<'_>,
    shape: &vexel_scene::Shape,
    x: f64,
    y: f64,
) -> Option<[u8; 4]> {
    let image = view.images.get(shape.image?)?;
    let p = affine_map_point(shape.stroke_inverse, Point { x, y })?;
    if p.x < image.x
        || p.y < image.y
        || p.x >= image.x + image.width
        || p.y >= image.y + image.height
        || p.x < image.draw_x
        || p.y < image.draw_y
        || p.x >= image.draw_x + image.draw_width
        || p.y >= image.draw_y + image.draw_height
        || image.draw_width <= 0.0
        || image.draw_height <= 0.0
    {
        return None;
    }
    let u = (p.x - image.draw_x) / image.draw_width;
    let v = (p.y - image.draw_y) / image.draw_height;
    let mut sx = u * image.pixels.width as f64 - 0.5;
    let mut sy = v * image.pixels.height as f64 - 0.5;
    sx = sx.clamp(0.0, (image.pixels.width - 1) as f64);
    sy = sy.clamp(0.0, (image.pixels.height - 1) as f64);
    let x0 = sx.floor() as usize;
    let y0 = sy.floor() as usize;
    let x1 = (x0 + 1).min(image.pixels.width as usize - 1);
    let y1 = (y0 + 1).min(image.pixels.height as usize - 1);
    let fx = sx - x0 as f64;
    let fy = sy - y0 as f64;
    let pix = |xx: usize, yy: usize| -> Option<[u8; 4]> {
        let o = yy
            .checked_mul(image.pixels.row_stride)?
            .checked_add(xx.checked_mul(4)?)?;
        Some(*<&[u8; 4]>::try_from(image.pixels.rgba.get(o..o + 4)?).ok()?)
    };
    let a = pix(x0, y0)?;
    let b = pix(x1, y0)?;
    let c = pix(x0, y1)?;
    let d = pix(x1, y1)?;
    let mut out = [0; 4];
    for k in 0..4 {
        let top = a[k] as f64 * (1.0 - fx) + b[k] as f64 * fx;
        let bot = c[k] as f64 * (1.0 - fx) + d[k] as f64 * fx;
        out[k] = (top * (1.0 - fy) + bot * fy).round().clamp(0.0, 255.0) as u8
    }
    let alpha = out[3];
    if alpha == 0 {
        return Some([0; 4]);
    }
    for c in 0..3 {
        out[c] = ((out[c] as u32 * 255 + alpha as u32 / 2) / alpha as u32).min(255) as u8
    }
    Some(out)
}
fn pattern_sample(
    view: SceneView<'_>,
    shape: &vexel_scene::Shape,
    paint: &Paint,
    x: f64,
    y: f64,
) -> Option<[u8; 4]> {
    let pattern = view.pattern(paint.pattern?)?;
    let p = affine_map_point(shape.stroke_inverse, Point { x, y })?;
    let tile = affine_map_point(paint.pattern_inverse, p)?;
    if !tile.x.is_finite() || !tile.y.is_finite() || tile.x.abs() > 1e12 || tile.y.abs() > 1e12 {
        return None;
    }
    let w = pattern.tile.width();
    let h = pattern.tile.height();
    let mut sx = (tile.x - 0.5) % (w as f64);
    let mut sy = (tile.y - 0.5) % (h as f64);
    if sx < 0.0 {
        sx += w as f64
    }
    if sy < 0.0 {
        sy += h as f64
    }
    let x0 = sx.floor() as usize;
    let y0 = sy.floor() as usize;
    let x1 = (x0 + 1) % w as usize;
    let y1 = (y0 + 1) % h as usize;
    let fx = sx - sx.floor();
    let fy = sy - sy.floor();
    let rgba = pattern.tile.rgba();
    let sample = |xx: usize, yy: usize| {
        let i = (yy * w as usize + xx) * 4;
        [rgba[i], rgba[i + 1], rgba[i + 2], rgba[i + 3]]
    };
    let p = [
        sample(x0, y0),
        sample(x1, y0),
        sample(x0, y1),
        sample(x1, y1),
    ];
    let weights = [
        (1.0 - fx) * (1.0 - fy),
        fx * (1.0 - fy),
        (1.0 - fx) * fy,
        fx * fy,
    ];
    let mut alpha = 0.0;
    let mut pm = [0.0; 3];
    for i in 0..4 {
        let a = p[i][3] as f64 / 255.0;
        alpha += a * weights[i];
        for c in 0..3 {
            pm[c] += p[i][c] as f64 / 255.0 * a * weights[i]
        }
    }
    if !paint.pattern_opacity.is_finite() || !(0.0..=1.0).contains(&paint.pattern_opacity) {
        return None;
    }
    let opacity = paint.pattern_opacity;
    alpha *= opacity;
    if alpha <= 0.0 {
        return Some([0; 4]);
    }
    let mut out = [0; 4];
    for c in 0..3 {
        out[c] = (pm[c] / (alpha / opacity) * 255.0)
            .round()
            .clamp(0.0, 255.0) as u8
    }
    out[3] = (alpha.min(1.0) * 255.0).round() as u8;
    Some(out)
}
fn allowed(
    view: SceneView<'_>,
    shape: &vexel_scene::Shape,
    input: &SampleInput<'_>,
    control: &mut dyn WorkControl,
) -> Result<bool> {
    let Some(clip) = shape.clip else {
        return Ok(true);
    };
    input
        .resources
        .clip_contains(view, clip, input.px, input.py, control)
}
fn stroke_paint(
    view: SceneView<'_>,
    id: ShapeId,
    input: &SampleInput<'_>,
    allowed: bool,
    alpha: AlphaMode,
    dst: &mut [u8; 4],
    control: &mut dyn WorkControl,
) -> Result<()> {
    if !allowed || !stroke_contains(view, id, input, control)? {
        return Ok(());
    }
    let Some(shape) = view.shape(id) else {
        return Ok(());
    };
    let Some(paint_i) = shape.stroke_paint else {
        if alpha == AlphaMode::FrozenOracleOnly {
            *dst = shape.stroke.rgba
        } else {
            over(dst, shape.stroke.rgba)
        }
        return Ok(());
    };
    let Some(p) = view.stroke_paints.get(paint_i) else {
        return Ok(());
    };
    let color = if p.kind == PaintKind::Pattern {
        pattern_sample(view, shape, p, input.px, input.py)
    } else if p.kind == PaintKind::Linear || p.kind == PaintKind::Radial {
        let mut c = input.resources.paint_sample(
            p,
            p.stops.slice(view.stops).unwrap_or(&[]),
            input.paint_x,
            input.paint_y,
        );
        c[3] = ((c[3] as u32 * shape.stroke.rgba[3] as u32 + 127) / 255) as u8;
        Some(c)
    } else {
        Some(shape.stroke.rgba)
    };
    if let Some(c) = color {
        if alpha == AlphaMode::FrozenOracleOnly && p.kind == PaintKind::Solid {
            *dst = c
        } else {
            over(dst, c)
        }
    }
    Ok(())
}
