    let n = view.shapes.len();
    let range_bytes = n
        .checked_mul(std::mem::size_of::<DashRange>())
        .ok_or_else(limit)?;
    if range_bytes > DASH_CACHE_BYTE_LIMIT {
        return Err(limit());
    }

