pub fn fill_row(
    view: SceneView<'_>,
    id: ShapeId,
    y: u32,
    scratch: &mut RasterScratch,
    map: ViewMapping,
    alpha: AlphaMode,
    resources: &dyn KernelResources,
    control: &mut dyn WorkControl,
) -> Result<()> {
    let shape = view.shape(id).ok_or(vexel_scene::Diagnostic {
        kind: vexel_scene::ErrorKind::InvalidArgument,
        offset: 0,
    })?;
    if y >= view.viewport.height
        || !map.scale_x.is_finite()
        || !map.scale_y.is_finite()
        || map.scale_x <= 0.0
        || map.scale_y <= 0.0
        || ![map.offset_x, map.offset_y].into_iter().all(f64::is_finite)
    {
        return Err(vexel_scene::Diagnostic {
            kind: vexel_scene::ErrorKind::InvalidArgument,
            offset: 0,
        });
    }
    let width = view.viewport.width as usize;
    let center_len = width.checked_mul(4).ok_or(vexel_scene::Diagnostic {
        kind: vexel_scene::ErrorKind::Limit(vexel_scene::LimitKind::Arithmetic),
        offset: 0,
    })?;
    let sub_len = width
        .checked_mul(FILL_SAMPLE_COUNT)
        .and_then(|x| x.checked_mul(4))
        .ok_or(vexel_scene::Diagnostic {
            kind: vexel_scene::ErrorKind::Limit(vexel_scene::LimitKind::Arithmetic),
            offset: 0,
        })?;
    if scratch.center_samples.len() < center_len {
        scratch
            .center_samples
            .try_reserve_exact(center_len - scratch.center_samples.len())
            .map_err(|_| vexel_scene::Diagnostic {
                kind: vexel_scene::ErrorKind::OutOfMemory,
                offset: 0,
            })?;
        scratch.center_samples.resize(center_len, 0)
    } else {
        scratch.center_samples[..center_len].fill(0)
    }
    if scratch.subpixel_samples.len() < sub_len {
        scratch
            .subpixel_samples
            .try_reserve_exact(sub_len - scratch.subpixel_samples.len())
            .map_err(|_| vexel_scene::Diagnostic {
                kind: vexel_scene::ErrorKind::OutOfMemory,
                offset: 0,
            })?;
        scratch.subpixel_samples.resize(sub_len, 0)
    } else {
        scratch.subpixel_samples[..sub_len].fill(0)
    }
    let locations = [0.125, 0.375, 0.625, 0.875];
    let edges: &[Edge] = shape
        .edges
        .slice(view.edges)
        .ok_or(vexel_scene::Diagnostic {
            kind: vexel_scene::ErrorKind::InvalidArgument,
            offset: 0,
        })?;
    let fill = shape
        .edges
        .slice(view.edge_colors)
        .and_then(|c| c.first())
        .copied()
        .unwrap_or([0; 4]);
    let mut edge_ids = Vec::new();
    edge_ids
        .try_reserve_exact(shape.edges.count)
        .map_err(|_| vexel_scene::Diagnostic {
            kind: vexel_scene::ErrorKind::OutOfMemory,
            offset: 0,
        })?;
    for x in shape.edges.first..shape.edges.first + shape.edges.count {
        edge_ids.push(u32::try_from(x).map_err(|_| vexel_scene::Diagnostic {
            kind: vexel_scene::ErrorKind::Limit(vexel_scene::LimitKind::Arithmetic),
            offset: 0,
        })?);
    }
    let empty = DashCache::default();
    let seams: Vec<bool> = Vec::new();
    for x in 0..width {
        for sy in 0..4 {
            for sx in 0..4 {
                control
                    .charge(vexel_scene::WorkKind::ShapeSample, 1)
                    .map_err(crate::stopped)?;
                let dx = x as f64 + locations[sx];
                let dy = y as f64 + locations[sy];
                let inside_view = dx >= map.offset_x
                    && dy >= map.offset_y
                    && dx < map.offset_x + view.viewport.view_width * map.scale_x
                    && dy < map.offset_y + view.viewport.view_height * map.scale_y;
                if !inside_view {
                    continue;
                }
                let px = view.viewport.view_x + (dx - map.offset_x) / map.scale_x;
                let py = view.viewport.view_y + (dy - map.offset_y) / map.scale_y;
                let input = SampleInput {
                    resources,
                    active_edges: &edge_ids,
                    local_edges: edges,
                    dash_seams: &seams,
                    dash_cache: &empty,
                    px,
                    py,
                    paint_x: px,
                    paint_y: py,
                };
                let c = paint_sample_inside(view, id, fill, &input, alpha, control)?;
                let si = (x * FILL_SAMPLE_COUNT + sy * 4 + sx) * 4;
                scratch.subpixel_samples[si..si + 4].copy_from_slice(&c)
            }
        }
    }
    for x in 0..width {
        let o = x * 4;
        let mut sums = [0u32; 4];
        for i in 0..FILL_SAMPLE_COUNT {
            let si = (x * FILL_SAMPLE_COUNT + i) * 4;
            for c in 0..4 {
                sums[c] += scratch.subpixel_samples[si + c] as u32
            }
        }
        for c in 0..4 {
            scratch.center_samples[o + c] = ((sums[c] + 8) / 16) as u8
        }
    }
    Ok(())
}

