                }
            }
            if crosses {
                continues = true
            }
            at = end;
            remain -= step;
            if remain <= DASH_EPSILON {
                pat = (pat + 1) % expanded;
                remain = dashes[pat % dashes.len()]
            }
        }
        if continues && i + 1 < n {
            let Some(next) = edges.get(first + i + 1) else {
                return false;
            };
            if join_hit(e.a, e.b, next.b, px, py, r, s.join, s.miter_limit) {
                return true;
            }
        }
        joins_prev = continues;
    }
    if closed && seam {
        if let (Some(a), Some(b)) = (edges.get(first + n - 1), edges.get(first)) {
            return join_hit(a.a, a.b, b.b, px, py, r, s.join, s.miter_limit);
        }
    }
    false
}

pub fn stroke_contains(
    view: SceneView<'_>,
    id: ShapeId,
    input: &SampleInput<'_>,
    control: &mut dyn WorkControl,
) -> Result<bool> {
    let Some(shape) = view.shape(id) else {
        return Ok(false);
    };
    let s = &shape.stroke;
    if s.rgba[3] == 0 || s.width <= 0.0 {
        return Ok(false);
    }
    if input
        .dash_cache
        .shapes
        .get(id.index())
        .is_some_and(|r| r.grid_columns != 0)
    {
        return Ok(dash_contains(
            view,
            shape,
            shape,
            id.index(),
            input.dash_cache,
            input.px,
            input.py,
        ));
    }
    let Some(_edge_range) = shape.edges.slice(input.local_edges) else {
        return Ok(false);
    };
    if !shape
        .subpaths
        .slice(view.path_subpaths)
        .unwrap_or(&[])
        .is_empty()
    {
        for (i, sub) in shape
            .subpaths
            .slice(view.path_subpaths)
            .unwrap()
            .iter()
            .enumerate()
        {
            control
                .charge(vexel_scene::WorkKind::StrokeTest, 1)
                .map_err(crate::stopped)?;
            let seam = input
                .dash_seams
                .get(view.shapes.len() + shape.subpaths.first + i)
                .copied()
                .unwrap_or(false);
            if range_contains(
                view,
                shape,
                sub.first_edge,
                sub.edge_count,
                sub.closed,
                true,
                seam,
                input.local_edges,
                input.px,
                input.py,
            ) {
                return Ok(true);
            }
        }
        Ok(false)
    } else {
        control
            .charge(vexel_scene::WorkKind::StrokeTest, shape.edges.count as u64)
            .map_err(crate::stopped)?;
        Ok(range_contains(
            view,
            shape,
            shape.edges.first,
            shape.edges.count,
            shape.stroke_closed,
            shape.filled,
            input.dash_seams.get(id.index()).copied().unwrap_or(false),
            input.local_edges,
            input.px,
            input.py,
        ))
    }
}
fn dash_contains(
