    };
    let Some(range) = cache.shapes.get(index) else {
        return false;
    };
    let r = shape.stroke.width * 0.5;
    if let Some(cell) = grid_lookup(range, local.x, local.y) {
        for &encoded in range
            .grid_refs
            .get(cell.first..cell.first.saturating_add(cell.count))
            .unwrap_or(&[])
        {
            if encoded & STROKE_GRID_JOIN_BIT != 0 {
                let j = encoded & !STROKE_GRID_JOIN_BIT;
                if let Some(join) = cache.joins.get(j as usize) {
                    let reach = if shape.stroke.join == Linejoin::Miter {
                        r * shape.stroke.miter_limit
                    } else {
                        r
                    };
                    if (local.x - join.vertex.x).abs() <= reach
                        && (local.y - join.vertex.y).abs() <= reach
                        && join_hit(
                            join.previous,
                            join.vertex,
                            join.next,
                            local.x,
                            local.y,
                            r,
                            shape.stroke.join,
                            shape.stroke.miter_limit,
                        )
                    {
                        return true;
                    }
                }
            } else if let Some(seg) = cache.segments.get(encoded as usize) {
                if segment_caps(
                    seg.edge.a,
                    seg.edge.b,
                    local.x,
                    local.y,
                    r,
                    seg.start_cap,
                    seg.end_cap,
                ) {
                    return true;
                }
            }
        }
        return false;
    }
    for seg in cache
        .segments
        .get(range.segments.first..range.segments.first.saturating_add(range.segments.count))
        .unwrap_or(&[])
    {
        let margin = if seg.start_cap == Linecap::Square || seg.end_cap == Linecap::Square {
            r * std::f64::consts::SQRT_2
        } else {
            r
        };
        if local.x >= seg.edge.a.x.min(seg.edge.b.x) - margin
            && local.x <= seg.edge.a.x.max(seg.edge.b.x) + margin
            && local.y >= seg.edge.a.y.min(seg.edge.b.y) - margin
            && local.y <= seg.edge.a.y.max(seg.edge.b.y) + margin
            && segment_caps(
                seg.edge.a,
                seg.edge.b,
                local.x,
                local.y,
                r,
                seg.start_cap,
                seg.end_cap,
            )
        {
            return true;
        }
    }
    let reach = if shape.stroke.join == Linejoin::Miter {
        r * shape.stroke.miter_limit
    } else {
        r
    };
    for j in cache
        .joins
        .get(range.joins.first..range.joins.first.saturating_add(range.joins.count))
        .unwrap_or(&[])
    {
        if (local.x - j.vertex.x).abs() <= reach
