            && join_hit(
                j.previous,
                j.vertex,
                j.next,
                local.x,
                local.y,
                r,
                shape.stroke.join,
                shape.stroke.miter_limit,
            )
        {
            return true;
        }
    }
    let _ = view;
    false
}
